"use client";
/**
 * EosGradientBanner: a grain gradient field holding app tiles. The field is layered linear and radial gradients from
 * the Eos set, two soft blurred petals in its glow colour, and SVG noise for grain. Pass children to hold anything
 * else instead of the tiles. The fill is the custom property --eos-banner-fill, so a stylesheet can swap it (a pale
 * frame, say) without remounting what the banner holds.
 *
 * The field drifts: the fill sits on a slightly oversized layer that sways a few per cent and half a degree, there and
 * back about every half minute, while the grain stays still on top. The drift runs on the compositor and only while
 * the banner is on screen in a visible tab; with reduced motion the field holds still. The layer takes the banner's
 * own background, so a stylesheet that changes the banner's background changes the layer too.
 */
import { useRef, type CSSProperties, type HTMLAttributes, type ReactNode } from "react";
import type { EosAppKind } from "./glyphs";
import { EosIconTile, type EosIconTileSize, type EosIconTileTone } from "./icon-tile";
import { useEosLoop } from "./motion";
import { cx } from "./shared";
import { EosScope } from "./theme";
import type { EosGradientName } from "./tokens";

const CSS = `
.eos-banner{position:relative;isolation:isolate;overflow:hidden;display:grid;place-items:center;box-sizing:border-box;border-radius:var(--eos-radius-banner);background:var(--eos-banner-fill)}
.eos-banner[data-shape=card]{border-radius:var(--eos-radius-card)}
.eos-banner[data-shape=square]{border-radius:0}
.eos-banner-field{position:absolute;inset:-7%;z-index:0;background:inherit;pointer-events:none}
.eos-banner-petal{position:absolute;z-index:0;border-radius:50%;pointer-events:none}
.eos-banner-petal[data-petal=a]{width:58%;height:150%;left:-20%;bottom:-88%;filter:blur(16px);transform:rotate(-14deg)}
.eos-banner-petal[data-petal=b]{width:12%;height:96%;right:13%;top:-34%;filter:blur(9px);opacity:.75;transform:rotate(30deg)}
.eos-banner[data-flip=true] .eos-banner-petal[data-petal=a]{left:auto;right:-22%;transform:rotate(16deg)}
.eos-banner[data-flip=true] .eos-banner-petal[data-petal=b]{right:auto;left:18%;transform:rotate(-26deg)}
.eos-banner-grain{position:absolute;inset:0;z-index:1;pointer-events:none;background-image:var(--eos-grain);background-size:200px 200px;mix-blend-mode:overlay;opacity:var(--eos-grain-opacity)}
.eos-banner-body{position:relative;z-index:2;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:14px;padding:20px;max-width:100%;box-sizing:border-box}
`;

export interface EosGradientBannerProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** Which field of the Eos set; the look and mode decide its tone. */
  gradient?: EosGradientName;
  /** The apps whose tiles sit in the field. */
  apps?: readonly EosAppKind[];
  tileTone?: EosIconTileTone;
  tileSize?: EosIconTileSize;
  height?: number | string;
  /** Corners: an inset banner inside a card (the default), a card of its own, or square. */
  shape?: "inset" | "card" | "square";
  /** Mirror the petals, so neighbouring banners differ. */
  flip?: boolean;
  petals?: boolean;
  grain?: boolean;
  /** Let the field drift slowly while it shows. */
  drift?: boolean;
  /** Anything to hold instead of the tiles. */
  children?: ReactNode;
}

export function EosGradientBanner({
  gradient = "dawn",
  apps = ["calendar", "mail", "notes"],
  tileTone = "white",
  tileSize = "md",
  height = 200,
  shape = "inset",
  flip = false,
  petals = true,
  grain = true,
  drift = true,
  children,
  className,
  style,
  ...rest
}: EosGradientBannerProps) {
  const field = useRef<HTMLDivElement>(null);
  useEosLoop(field, drift);
  return (
    <EosScope>
      <style>{CSS}</style>
      <div
        {...rest}
        ref={field}
        className={cx("eos-banner", className)}
        data-gradient={gradient}
        data-shape={shape}
        data-flip={flip}
        style={{ "--eos-banner-fill": `var(--eos-gradient-${gradient})`, height, ...style } as CSSProperties}
      >
        {drift && <span className="eos-banner-field eos-drift" aria-hidden />}
        {petals && (
          <>
            <span className="eos-banner-petal" data-petal="a" style={{ background: `var(--eos-glow-${gradient})` }} aria-hidden />
            <span className="eos-banner-petal" data-petal="b" style={{ background: `var(--eos-glow-${gradient})` }} aria-hidden />
          </>
        )}
        {grain && <span className="eos-banner-grain" aria-hidden />}
        <div className="eos-banner-body">
          {children ??
            apps.map((app, i) => <EosIconTile key={`${app}-${i}`} app={app} tone={tileTone} size={tileSize} style={{ "--eos-tile-i": i } as CSSProperties} />)}
        </div>
      </div>
    </EosScope>
  );
}

// @zeus-internal
/** Small helpers the Eos pieces share. */
import { useCallback, useEffect, useLayoutEffect, useState } from "react";

export const cx = (...parts: (string | false | null | undefined)[]) => parts.filter(Boolean).join(" ");

export const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** A value that is controlled when `value` is given and owned here otherwise. */
export function useControlled<T>(value: T | undefined, initial: T, onChange?: (next: T) => void) {
  const [own, setOwn] = useState(initial);
  const current = value === undefined ? own : value;
  const set = useCallback(
    (next: T) => {
      if (value === undefined) setOwn(next);
      onChange?.(next);
    },
    [value, onChange],
  );
  return [current, set] as const;
}

/**
 * Whether a media query matches. The server and the first render use `initial`, so markup hydrates; the real answer
 * follows once mounted, and changes as the window does.
 */
export function useMedia(query: string, initial = false): boolean {
  const [matches, setMatches] = useState(initial);
  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const list = window.matchMedia(query);
    const update = () => setMatches(list.matches);
    update();
    list.addEventListener?.("change", update);
    return () => list.removeEventListener?.("change", update);
  }, [query]);
  return matches;
}

/** The index a roving-focus key moves to, or -1 for a key the group ignores. */
export function rovingIndex(key: string, index: number, count: number): number {
  if (count === 0) return -1;
  if (key === "ArrowRight" || key === "ArrowDown") return (index + 1) % count;
  if (key === "ArrowLeft" || key === "ArrowUp") return (index - 1 + count) % count;
  if (key === "Home") return 0;
  if (key === "End") return count - 1;
  return -1;
}

/** Visually hidden text for assistive technology. */
export const SR_ONLY_CSS =
  ".eos-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}";
